<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#E5C07B;"> Thread</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">VolatileRead</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">ref</span><span style="color:#E06C75;"> s_value</span><span style="color:#ABB2BF;">);</span></span>
